def is_chain_valid(chain):
    for i in range(1, len(chain)):
        current = chain[i]
        previous = chain[i-1]
        if current.prev_hash != previous.hash:
            return False
        if current.hash != current._compute_hash():
            return False
    return True

# Tampering detection
chain[1].data = 'Fake data'
chain[1].hash = chain[1]._compute_hash()  # fix own hash
print(is_chain_valid(chain))  # False, because next block's prev_hash no longer matches
